import{_ as t,o as a,c as n,ag as r}from"./chunks/framework.2cFhd8Ux.js";const u=JSON.parse('{"title":"Week 1 — From Vibe Coding to Agentic Engineering","description":"","frontmatter":{"source":"weeks/01-agentic-engineering/README.md"},"headers":[],"relativePath":"weeks/01-agentic-engineering/index.md","filePath":"weeks/01-agentic-engineering/index.md"}'),o={name:"weeks/01-agentic-engineering/index.md"};function s(i,e,d,h,l,g){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="week-1--from-vibe-coding-to-agentic-engineering" tabindex="-1">Week 1 — From Vibe Coding to Agentic Engineering <a class="header-anchor" href="#week-1--from-vibe-coding-to-agentic-engineering" aria-label="Permalink to &quot;Week 1 — From Vibe Coding to Agentic Engineering&quot;">​</a></h1><blockquote><p>A coding agent is a model in a loop with tools, and engineering with one means deciding what you specify, what you delegate and how you will verify it before the agent starts.</p></blockquote><h2 id="this-week-at-a-glance" tabindex="-1">This week at a glance <a class="header-anchor" href="#this-week-at-a-glance" aria-label="Permalink to &quot;This week at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>Before the Seminar</strong></td><td>Finish <a href="./../../setup/">setup</a> (accounts, a free API key, a test Codespace) and read the <a href="./../../setup/safety-contract.html">agent safety contract</a>. Bring a laptop</td></tr><tr><td><strong>Seminar</strong></td><td>How the course works and is graded · Specify · Delegate · Verify; observed and inferred · LLMs for engineers: tokens, context windows, sampling, tool calling, cost · the evidence teaser: maintainers vs graders · the safety contract · a live demo (<a href="https://boyu-zhang-uoi.github.io/engineering-software-with-ai/slides/week-01.html" target="_blank" rel="noreferrer">slides</a>)</td></tr><tr><td><strong>Lab</strong></td><td>Run the <a href="https://github.com/Boyu-Zhang-UOI/eswa-mini-agent" target="_blank" rel="noreferrer"><code>mini-agent</code> kit</a> in a Codespace, read its loop, run a task with every change approved, read its JSONL trace. <strong>Checkoff:</strong> the completed task, every write and command approved by you, the trace shown (<a href="./lab.html#lab--run-and-read-a-coding-agent-75-min">lab</a>)</td></tr><tr><td><strong>Due before next week&#39;s Seminar</strong></td><td>Default 11:59 pm the night before: the <a href="./lab.html#assignment--extend-the-agent-and-dissect-a-real-one">assignment</a>: a new tool with tests, one extension, a trace dissection of a real CLI agent, <code>AI_LOG.md</code>. No quiz this week; week 2 opens with one on this work</td></tr><tr><td><strong>AI use this week</strong></td><td>🟢 AI on: the extension code and tests; the CLI agent session you dissect · 🔴 AI off: reading the loop (Lab Part 2), the dissection&#39;s annotations, the reading response</td></tr><tr><td><strong>Reading</strong></td><td>METR, <a href="https://metr.org/notes/2026-03-10-many-swe-bench-passing-prs-would-not-be-merged-into-main/" target="_blank" rel="noreferrer">&quot;Many SWE-bench-Passing PRs Would Not Be Merged into Main&quot;</a> (2026)</td></tr><tr><td><strong>Reading response</strong></td><td>150–250 words on Canvas, 🔴 AI off, due <strong>before the week 1 Lab</strong> (this week only) (<a href="#reading">prompt</a>)</td></tr><tr><td><strong>Team project</strong></td><td>The team-formation survey on Canvas. Teams of 3–4 are announced in week 2 (<a href="./../../project/#teams">teams</a>)</td></tr><tr><td><strong>Graduate track</strong></td><td>CS [5xxx]: rank three papers from the <a href="./../../graduate/paper-presentations.html#the-papers">paper list</a> on Canvas (off-list proposals by the end of the week); skim the <a href="./../../resources/reading-list.html#replicable-studies">replicable studies</a></td></tr><tr><td><strong>Time</strong></td><td>Seminar and Lab 2.5 h · outside about 6 h (CS [5xxx] about 7.5): reading 45 min, Canvas forms 20 min, assignment about 4.5 h</td></tr></tbody></table><p>Also on Canvas this week: <strong>sign the agent safety contract</strong>. It is personal: never commit it.</p><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><p>By the end of this week you can:</p><ol><li>Explain an agent as a model, a harness, tools and a loop, and point to each in <code>mini-agent</code>&#39;s code.</li><li>Use tokens, context windows, sampling and tool calling to predict what an agent costs and why two runs differ.</li><li>Run an agent with approvals on in a sandbox, and say what the approval gate, the workspace guard and the sandbox each stop.</li><li>Reconstruct from a JSONL trace what the model saw and did at each step.</li><li>Tag any claim about an agent <strong>observed</strong> or <strong>inferred</strong>, and turn an inferred claim into an observed one.</li><li>Extend a small agent with a tool and tests that run offline against a scripted model.</li></ol><h2 id="seminar" tabindex="-1">Seminar <a class="header-anchor" href="#seminar" aria-label="Permalink to &quot;Seminar&quot;">​</a></h2><p>The ground rules (<a href="./../../SYLLABUS.html">syllabus</a>; <a href="./../../assessment/">assessment</a>), the ideas the term builds on, a debate about why maintainers rejected test-passing agent PRs, and a live run of this week&#39;s agent. <a href="https://boyu-zhang-uoi.github.io/engineering-software-with-ai/slides/week-01.html" target="_blank" rel="noreferrer">Slides</a>.</p><h2 id="lab" tabindex="-1">Lab <a class="header-anchor" href="#lab" aria-label="Permalink to &quot;Lab&quot;">​</a></h2><p>Run and read <code>mini-agent</code>, a working agent of a few hundred lines; then extend it and take apart a session with a production CLI agent. <a href="./lab.html">Lab and assignment</a>.</p><h2 id="reading" tabindex="-1">Reading <a class="header-anchor" href="#reading" aria-label="Permalink to &quot;Reading&quot;">​</a></h2><p>METR, <a href="https://metr.org/notes/2026-03-10-many-swe-bench-passing-prs-would-not-be-merged-into-main/" target="_blank" rel="noreferrer">&quot;Many SWE-bench-Passing PRs Would Not Be Merged into Main&quot;</a> (March 2026), the reading list&#39;s <a href="./../../resources/reading-list.html#week-1--from-vibe-coding-to-agentic-engineering">core pick</a>. It&#39;s short.</p><p><strong>Reading response</strong> (150–250 words, 🔴 AI off, on Canvas, before the week 1 Lab; <a href="./../../assessment/rubrics.html#reading-response-5-points">rubric</a>): state the main finding with one number. What did the maintainers judge that the automated grader didn&#39;t? How strong is the evidence (who reviewed, how many PRs, which projects), and would it hold for a codebase like your team&#39;s? What will you check in your own agent&#39;s work because of it? End with one question for the Seminar.</p><h2 id="key-ideas" tabindex="-1">Key ideas <a class="header-anchor" href="#key-ideas" aria-label="Permalink to &quot;Key ideas&quot;">​</a></h2><p><strong>Vibe coding vs agentic engineering.</strong> <a href="./../../resources/glossary.html#vibe-coding">Vibe coding</a> accepts AI-written code without reading it, which is fine for a throwaway. <a href="./../../resources/glossary.html#agentic-engineering">Agentic engineering</a> uses the same agents and keeps you responsible for the specification, the verification and the result.</p><p><strong>Specify · Delegate · Verify.</strong> Before the agent starts, decide what must be true when it finishes, what goes to which agent with what permissions, and what evidence will show it&#39;s right (<a href="./../../resources/safe-loop.html#specify--delegate--verify">Safe Loop</a>; UT Austin <a href="https://www.cs.utexas.edu/~witchel/378AC/index.html" target="_blank" rel="noreferrer">CS 378</a>&#39;s framing). Tag every claim <a href="./../../resources/glossary.html#observed-and-inferred">observed or inferred</a>: &quot;the agent says the tests pass&quot; is inferred; &quot;<code>node --test</code>: 3 pass, 0 fail&quot; is observed.</p><p><strong>Tokens, context and sampling.</strong> A model reads and writes <a href="./../../resources/glossary.html#token">tokens</a>. The <a href="./../../resources/glossary.html#context-window">context window</a> holds the system prompt, the tool schemas, the conversation and every file read, and the harness resends all of it each turn, so long sessions get slow, expensive and worse. Each token is sampled, so the same task can produce different tool calls: judge outcomes with checks you can rerun.</p><p><strong>Tool calling.</strong> The model never runs anything. It returns a <a href="./../../resources/glossary.html#tool-call">tool call</a>, JSON naming a tool and its arguments, and the <a href="./../../resources/glossary.html#harness">harness</a> decides whether to run it. Every safety property lives in the harness and the sandbox.</p><p><strong>The loop is small.</strong> <a href="https://github.com/SWE-agent/mini-swe-agent" target="_blank" rel="noreferrer">mini-swe-agent</a> is about 100 lines with one bash tool; <a href="https://ampcode.com/how-to-build-an-agent" target="_blank" rel="noreferrer">Thorsten Ball&#39;s agent</a> is under 400. What makes an agent safe and useful is everything around the loop: week 2.</p><p><strong>Passing is not mergeable.</strong> Four maintainers of scikit-learn, Sphinx and pytest reviewed 296 test-passing agent PRs; their merge rate ran 24.2 points below an automated grader&#39;s, and they merged only 68% of the human-written reference patches (<a href="https://metr.org/notes/2026-03-10-many-swe-bench-passing-prs-would-not-be-merged-into-main/" target="_blank" rel="noreferrer">METR</a>; <a href="./../../resources/case-studies.html#d5-maintainers-vs-graders">case D5</a>). Feeling fast isn&#39;t being fast either: in a randomized trial, 16 experienced open-source developers took 19% longer with early-2025 AI tools on 246 real tasks, yet believed they&#39;d been about 20% faster (<a href="https://arxiv.org/abs/2507.09089" target="_blank" rel="noreferrer">Becker et al.</a>).</p><p><strong>Safety lives outside the model.</strong> Approvals on, untrusted code in a sandbox, no real secrets in reach, spending caps at zero (<a href="./../../setup/safety-contract.html">contract</a>).</p><h2 id="check-your-understanding" tabindex="-1">Check your understanding <a class="header-anchor" href="#check-your-understanding" aria-label="Permalink to &quot;Check your understanding&quot;">​</a></h2><ol><li>Your agent&#39;s fifth turn sends about five times as many tokens as its first, for the same task. Why?</li><li>Two runs of one task make different tool calls. Name two causes, and say how you&#39;d decide whether either run was correct.</li><li>In <code>mini-agent</code>, does the approval gate or the workspace guard run first for <code>edit_file</code>? What happens if you approve an edit to <code>../.env</code>?</li><li>The kit&#39;s README says nothing the agent does can read your home directory. Is that true of <code>run_command</code>? What stops <code>cat ~/.bashrc</code>?</li></ol><details><summary>Answers</summary><ol><li>Each turn resends the system prompt, the schemas and the whole growing history. 2. Sampling, and a different model or provider; decide with an outcome check such as the tests. 3. The gate runs first; the handler then calls <code>resolveInside</code>, which still refuses the escape, and the model reads the error. 4. No: <code>run_command</code> hands the string to <code>/bin/sh</code> in the workspace, and nothing checks paths inside it. Your &quot;no&quot; at the gate stops it; without that, only the sandbox limits the damage.</li></ol></details><h2 id="if-a-tool-is-down" tabindex="-1">If a tool is down <a class="header-anchor" href="#if-a-tool-is-down" aria-label="Permalink to &quot;If a tool is down&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problem</th><th>What to do</th></tr></thead><tbody><tr><td>The free API returns 429 or 5xx</td><td>The kit retries with backoff. If it persists, switch to the fallback provider in <code>.env</code> (<a href="./../../TOOLS.html#llm-apis-for-the-kits">Tool Handout: LLM APIs for the kits</a>; <a href="./../../resources/troubleshooting.html#my-api-call-fails-401-404-429">troubleshooting</a>)</td></tr><tr><td>Out of Codespaces hours</td><td>A dev container on your laptop (<a href="./../../setup/sandboxes.html#dev-containers-on-your-laptop">sandboxes</a>); on campus or the VPN it can also use the <a href="./../../setup/local-models.html#on-the-lab-machine">lab machine</a></td></tr><tr><td>The model answers in prose instead of calling tools</td><td>The next model in TOOLS.md, or the <a href="./../../setup/local-models.html#the-tool-calling-smoke-test">smoke test</a> (<a href="./../../resources/troubleshooting.html#the-local-model-ignores-its-tools">troubleshooting</a>)</td></tr><tr><td>No CLI agent works for the dissection</td><td>Any agent in the <a href="./../../TOOLS.html#the-stack-at-a-glance">stack table</a>; as a last resort, a long <code>mini-agent</code> trace, said so in the write-up</td></tr></tbody></table><h2 id="going-further" tabindex="-1">Going further <a class="header-anchor" href="#going-further" aria-label="Permalink to &quot;Going further&quot;">​</a></h2><ul><li>Kwa et al., <a href="https://arxiv.org/abs/2503.14499" target="_blank" rel="noreferrer">&quot;Measuring AI Ability to Complete Long Software Tasks&quot;</a>, NeurIPS 2025: the 50% <a href="./../../resources/glossary.html#time-horizon">time horizon</a>, doubling roughly every 7 months since 2019. <strong>[Grad seminar]</strong></li><li>METR, <a href="https://metr.org/blog/2025-08-12-research-update-towards-reconciling-slowdown-with-time-horizons" target="_blank" rel="noreferrer">&quot;Algorithmic vs. Holistic Evaluation&quot;</a> (2025): none of 15 agent PRs was mergeable as-is, though 38% passed the tests.</li><li>More in the <a href="./../../resources/reading-list.html#week-1--from-vibe-coding-to-agentic-engineering">reading list</a>.</li></ul>',30)])])}const m=t(o,[["render",s]]);export{u as __pageData,m as default};
